# Generated by test-lab — blind adversarial evaluation
"""Pure-logic tests for LinkedIn advanced-search URL/query construction.

These prove the search-URL builder maps candidate preferences to LinkedIn's own
filter params correctly WITHOUT any browser/surf calls, so the advanced-search
capture is ready and verified the moment surf is stable.
"""

from __future__ import annotations

import json
import subprocess
from urllib.parse import parse_qs, urlparse

import monitor_opportunities.browser_capture as bc
from monitor_opportunities.browser_capture import (
    _LINKEDIN_SENIOR_EXPERIENCE,
    build_linkedin_search_url,
    capture_linkedin_premium,
    capture_linkedin_top_applicant,
    linkedin_search_queries_from_profile,
)


def _params(url: str) -> dict[str, list[str]]:
    return parse_qs(urlparse(url).query)


def test_remote_hybrid_maps_to_f_wt_2_3() -> None:
    url = build_linkedin_search_url("document extraction AI", ["remote", "hybrid"])
    p = _params(url)
    assert p["keywords"] == ["document extraction AI"]
    assert p["f_WT"] == ["2,3"]
    assert p["f_E"] == [",".join(_LINKEDIN_SENIOR_EXPERIENCE)]
    assert p["sortBy"] == ["DD"]


def test_onsite_and_location_present_for_buffalo() -> None:
    url = build_linkedin_search_url(
        "AI architect", ["on-site", "remote", "hybrid"], location="Buffalo, NY"
    )
    p = _params(url)
    assert p["f_WT"] == ["1,2,3"]
    assert p["location"] == ["Buffalo, NY"]


def test_unknown_work_type_ignored_no_empty_f_wt() -> None:
    url = build_linkedin_search_url("x", ["teleport"])
    assert "f_WT" not in _params(url)


def test_empty_experience_levels_omits_f_e() -> None:
    url = build_linkedin_search_url("x", ["remote"], experience_levels=[])
    assert "f_E" not in _params(url)


def test_query_set_has_remote_and_buffalo_per_group() -> None:
    profile = {
        "mandates": ["agentic-compliance (flagship: sparta)", "document-extraction (flagships: pdf_oxide)"],
        "workplace_preference": {"preferred": ["remote", "hybrid"]},
        "identity": {"location": "Buffalo, NY"},
    }
    queries = linkedin_search_queries_from_profile(profile)
    labels = [q["label"] for q in queries]
    assert any("remote+hybrid" in l for l in labels)
    assert any("Buffalo, NY on-site OK" in l for l in labels)
    # every url is a well-formed LinkedIn job-search URL
    for q in queries:
        assert q["url"].startswith("https://www.linkedin.com/jobs/search/?")
        assert "keywords=" in q["url"]


def test_empty_mandates_falls_back_not_empty() -> None:
    queries = linkedin_search_queries_from_profile({})
    assert queries  # never silently empty
    for q in queries:
        assert "keywords=" in q["url"]


def test_easy_apply_filter() -> None:
    p = _params(build_linkedin_search_url("AI architect", ["remote"], easy_apply=True))
    assert p["f_AL"] == ["true"]
    p2 = _params(build_linkedin_search_url("AI architect", ["remote"]))
    assert "f_AL" not in p2


def test_top_applicant_capture_receipts_easy_apply_count(tmp_path, monkeypatch) -> None:
    monkeypatch.setattr(bc, "ensure_browser", lambda surf_run: None)
    monkeypatch.setattr(bc, "_surf_pause", lambda *args, **kwargs: None)
    monkeypatch.setattr(bc, "_close_tab", lambda *args, **kwargs: None)
    monkeypatch.setattr(
        bc,
        "_linkedin_scroll_paginate_capture",
        lambda surf_run, tab_id: [
            {
                "title": "Principal AI Architect",
                "company": "Moog",
                "location": "Buffalo, NY",
                "href": "https://www.linkedin.com/jobs/view/123/",
                "easy_apply": True,
            },
            {
                "title": "Staff AI Engineer",
                "company": "Acme",
                "location": "Remote",
                "href": "https://www.linkedin.com/jobs/view/456/",
                "easy_apply": False,
            },
        ],
    )

    def fake_surf(_surf_run, command, *args, **kwargs):
        if command == "tab.new":
            return "123: created"
        return "OK"

    monkeypatch.setattr(bc, "_surf", fake_surf)

    receipt = capture_linkedin_top_applicant(tmp_path)
    evidence = json.loads((tmp_path / "linkedin-top-applicant-evidence.json").read_text(encoding="utf-8"))

    assert receipt["status"] == "OK"
    assert receipt["opportunities_captured"] == 2
    assert receipt["top_applicant_count"] == 2
    assert receipt["easy_apply_count"] == 1
    assert [row["easy_apply"] for row in evidence["opportunities"]] == [True, False]


def test_top_applicant_js_skips_verification_badge_line() -> None:
    script = f"""
const card = {{
  innerText: "Principal AI Architect\\nPrincipal AI Architect with verification\\nMoog\\nBuffalo, NY\\nEasy Apply",
  querySelector: function(sel) {{
    if (sel.indexOf('/jobs/view/') >= 0 || sel.indexOf('currentJobId') >= 0) {{
      return {{href: 'https://www.linkedin.com/jobs/view/123/?trk=x'}};
    }}
    return null;
  }}
}};
global.document = {{ querySelectorAll: function() {{ return [card]; }} }};
console.log(eval({json.dumps(bc._LINKEDIN_EXTRACT_JS)}));
"""
    rows = json.loads(subprocess.check_output(["node", "-e", script], text=True))

    assert rows[0]["title"] == "Principal AI Architect"
    assert rows[0]["company"] == "Moog"
    assert rows[0]["location"] == "Buffalo, NY"
    assert rows[0]["easy_apply"] is True


def test_premium_capture_receipt_exposes_zero_top_applicant_and_easy_apply_counts(tmp_path, monkeypatch) -> None:
    monkeypatch.setattr(bc, "ensure_browser", lambda surf_run: None)
    monkeypatch.setattr(bc, "_surf_pause", lambda *args, **kwargs: None)
    monkeypatch.setattr(bc, "_close_tab", lambda *args, **kwargs: None)
    monkeypatch.setattr(
        bc,
        "linkedin_search_queries_from_profile",
        lambda profile: [{"label": "agentic AI engineer | remote+hybrid", "url": "https://www.linkedin.com/jobs/search/?keywords=agentic"}],
    )

    def fake_surf(_surf_run, command, *args, **kwargs):
        if command == "tab.new":
            return "456: created"
        script = " ".join(str(arg) for arg in args)
        if "location.href" in script:
            return "NAV"
        rows = [
            {
                "title": "Senior AI Engineer",
                "company": "Example",
                "location": "Remote",
                "href": "https://www.linkedin.com/jobs/view/789/",
                "early": True,
                "warm": False,
            }
        ]
        return json.dumps(json.dumps(rows))

    monkeypatch.setattr(bc, "_surf", fake_surf)

    receipt = capture_linkedin_premium(tmp_path, profile={})

    assert receipt["status"] == "OK"
    assert receipt["opportunities_captured"] == 1
    assert receipt["top_applicant_count"] == 0
    assert receipt["easy_apply_count"] == 0
    assert receipt["under_10_applicants_count"] == 1


def test_premium_js_skips_verification_badge_line() -> None:
    script = f"""
const card = {{
  innerText: "Senior AI Engineer\\nSenior AI Engineer with verification\\nMoog\\nBuffalo, NY\\n3 hours ago\\nBe an early applicant\\nconnection works here",
  parentElement: null,
  getAttribute: function(name) {{
    if (name === 'componentkey') return 'job-card-component-ref-789';
    return null;
  }},
  querySelector: function() {{ return null; }}
}};
const button = {{
  parentElement: card,
  getAttribute: function(name) {{
    if (name === 'aria-label') return 'Dismiss Senior AI Engineer job';
    return null;
  }}
}};
const bareDismiss = {{
  parentElement: card,
  getAttribute: function(name) {{
    if (name === 'aria-label') return 'Dismiss';
    return null;
  }}
}};
global.document = {{ querySelectorAll: function() {{ return [bareDismiss, button]; }} }};
console.log(eval({json.dumps(bc._LI_ARIA_EXTRACT_JS)}));
"""
    rows = json.loads(subprocess.check_output(["node", "-e", script], text=True))

    assert len(rows) == 1
    assert rows[0]["title"] == "Senior AI Engineer"
    assert rows[0]["company"] == "Moog"
    assert rows[0]["location"] == "Buffalo, NY"
    assert rows[0]["early"] is True
    assert rows[0]["warm"] is True
    assert rows[0]["href"] == "https://www.linkedin.com/jobs/view/789/"


def test_premium_capture_reports_failed_when_all_browser_queries_fail(tmp_path, monkeypatch) -> None:
    monkeypatch.setattr(bc, "ensure_browser", lambda surf_run: None)
    monkeypatch.setattr(bc, "_surf_pause", lambda *args, **kwargs: None)
    monkeypatch.setattr(bc, "_close_tab", lambda *args, **kwargs: None)
    monkeypatch.setattr(
        bc,
        "linkedin_search_queries_from_profile",
        lambda profile: [
            {
                "label": "agentic AI engineer | remote+hybrid",
                "url": "https://www.linkedin.com/jobs/search/?keywords=agentic",
            }
        ],
    )

    def fake_surf(_surf_run, command, *args, **kwargs):
        del args, kwargs
        if command == "tab.new":
            return "456: created"
        raise bc.BrowserCaptureError("surf js failed: target closed")

    monkeypatch.setattr(bc, "_surf", fake_surf)

    receipt = capture_linkedin_premium(tmp_path, profile={})

    assert receipt["status"] == "FAILED"
    assert receipt["error"] == "all LinkedIn Premium browser queries failed"
    assert receipt["opportunities_captured"] == 0
    assert len(receipt["query_failures"]) == 3
    assert all("surf js failed" in row["error"] for row in receipt["query_failures"])
